import {Game} from './game.js';
import {render,plantImage,bossImage,enemyImage} from './render.js';
import {animateSunCollection} from './art/collection.js';
import {PLANTS,BALANCE as B,CLASSES,METRICS,ZOMBIES,ELITE_MODIFIERS} from './data.js';
import {PLANT_LEVELS} from './plantUpgrades.js';
import {UPGRADES,RARITIES,affects} from './roguelikeUpgrades.js';
import {EVOLUTIONS} from './evolutions.js';
import {MAP,TERRAIN,tileCount,screenToWorld,mapDefinition} from './map.js';
import {GARDEN_ORDER} from './gardens.js';
import {read,write,validate,download,fresh} from './save.js';
const $=id=>document.getElementById(id),canvas=$('game'),field=canvas.closest('.field'),ctx=canvas.getContext('2d'),modal=$('modal'),images=Object.fromEntries(PLANTS.map(p=>[p.id,plantImage(p.id)])),enemyImages=Object.fromEntries(ZOMBIES.map(z=>[z.id,enemyImage(z)]));canvas.width=MAP.cols*MAP.tileSize;canvas.height=MAP.rows*MAP.tileSize;
let meta=read(),selected='peashooter',hover=null,inspected=null,last=performance.now(),acc=0,toastTimer,screen='menu',started=false,inspectionKey='',cardsKey='',pickupsKey='';
const fmt=n=>Number.isFinite(n)?Number(n.toFixed(1)).toLocaleString('pt-BR'):'—',clock=t=>Math.floor(t/60).toString().padStart(2,'0')+':'+Math.floor(t%60).toString().padStart(2,'0');
const iconPaths={play:'M8 5l12 7-12 7z',plants:'M12 21V10M12 14C3 15 3 7 3 4c7 0 10 4 9 10M12 10c0-5 4-7 9-7 0 6-3 10-9 10',upgrades:'M12 21V4M5 11l7-7 7 7',stats:'M5 20V12M12 20V4M19 20V8',save:'M5 3h13l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',settings:'M12 3v3M12 18v3M3 12h3M18 12h3M6 6l2 2M16 16l2 2M6 18l2-2M16 8l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
const icon=k=>'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="'+iconPaths[k]+'"/></svg>';
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),2800)}
function persist(){const ok=write(meta);if(!ok)toast('Não foi possível salvar. Exporte o TXT para guardar seu progresso.');return ok}
function show(html,name){screen=name;hover=null;g.setPointerWorld(0,0,false);$('modal-content').innerHTML=html;if(!modal.open)modal.showModal()}
function close(){if(modal.open)modal.close();screen='game';g.paused=false;last=performance.now();acc=0;inspectionKey='';update()}
function title(name){return '<div class="dialog-top"><h2 id="dialog-title">'+name+'</h2><button id="back">Voltar</button></div>'}
function bindBack(fn=menu){$('back').onclick=fn}
function targetName(target){return PLANTS.find(p=>p.id===target)?.name||CLASSES[target?.replace?.('class:','')]||({global:'Todas as plantas',economy:'Economia',base:'Jardim'}[target])||target}
const metricLabels={sunSpawned:'Sun gerado',sunCollected:'Sun coletado',sunMissed:'Sun perdido',sunflowerSun:'Sun de Sunflowers',naturalSun:'Sun natural',plantsPlaced:'Plantas colocadas',plantsLost:'Plantas perdidas',damageDealt:'Dano causado',bossesDefeated:'Bosses derrotados',highestBossWave:'Maior boss wave',sunsAutoCollected:'Suns coletados pelo Magnet',sectorsExpanded:'Setores expandidos',evolutionsChosen:'Evolutions escolhidas'};
const g=new Game(meta,onWave,onEnd);
g.events.on('boss:spawn',({boss,gardenId})=>toast('BOSS FRONT · '+(g.gardens[gardenId]?.name||'FRONT YARD')+' · '+boss.name));g.events.on('boss:defeated',()=>toast('Boss derrotado! +3 Plant Food · +1 Reroll'));g.events.on('sector:unlocked',({sector,gardenId})=>toast((g.gardens[gardenId]?.name||g.activeGarden.name)+' · '+sector.name+' desbloqueado'));g.events.on('sun:collected',({drop,automatic})=>{if(drop.gardenId===g.activeGardenId)animateSunCollection(drop,canvas,$('sun'),automatic)});g.events.on('garden:underPressure',({garden,level})=>toast('⚠ '+garden.name+' '+(level==='CRITICAL'?'CRITICAL':'UNDER ATTACK')));g.events.on('garden:lost',({garden})=>toast(garden.name+' LOST'));g.events.on('garden:switched',()=>{hover=null;inspected=null;inspectionKey='';cardsKey='';pickupsKey='';update()});
function newRun(){g.meta=meta;g.reset();selected='peashooter';inspected=null;started=true;close();toast('Prepare sua defesa. Consulte o plano da próxima wave.')}
function onEnd(){const record=g.wave>meta.highestWave;meta.seeds+=g.earned;meta.highestWave=Math.max(meta.highestWave,g.wave);meta.totalRuns++;meta.kills+=g.kills;meta.time+=Math.floor(g.combatTime);meta.bossStats.totalBossesDefeated+=g.bossesDefeated;meta.bossStats.highestBossWave=Math.max(meta.bossStats.highestBossWave,g.metrics.highestBossWave);for(const k of METRICS)meta.statistics[k]=k==='highestBossWave'?Math.max(meta.statistics[k],Math.floor(g.metrics[k])):meta.statistics[k]+Math.floor(g.metrics[k]);meta.favorites.plant=Object.entries(g.plantUsage).sort((a,b)=>b[1]-a[1])[0]?.[1]>0?Object.entries(g.plantUsage).sort((a,b)=>b[1]-a[1])[0][0]:meta.favorites.plant;meta.favorites.evolution=Object.values(g.selectedEvolutions).at(-1)||meta.favorites.evolution;persist();showGameOver(record)}
function gardenSummary(){return GARDEN_ORDER.filter(id=>g.gardens[id]).map(id=>{const garden=g.gardens[id];return '<div class="garden-summary '+(garden.lost?'lost':'')+'"><b>'+garden.name+'</b><span>'+(garden.lost?'Lost':'Active')+' · '+garden.condition.name+'</span></div>'}).join('')}
function showGameOver(record){show('<small>'+(record?'NOVO RECORDE!':'FIM DA RUN')+'</small><h2 id="dialog-title">Uma nova chance de florescer.</h2><div class="metric-grid">'+[['Wave',g.wave],['Bosses',g.bossesDefeated],['Gardens',g.gardensUnlocked],['Gardens perdidos',g.gardensLost],['Zumbis',g.kills],['Seeds ganhos','+'+g.earned]].map(([k,v])=>'<div>'+k+'<b>'+v+'</b></div>').join('')+'</div><h3>Gardens</h3><div class="garden-summary-list">'+gardenSummary()+'</div><div class="save-actions"><button id="run-build">Ver build final</button><button class="primary" id="again">Jogar novamente</button><button id="return">Menu</button></div>','over');$('run-build').onclick=()=>buildView(()=>showGameOver(record));$('again').onclick=newRun;$('return').onclick=menu;update()}
function preview(u){if(u.target==='base')return u.id==='foundation'?'HP máximo: '+fmt(g.maxHp)+' → '+fmt(g.maxHp*1.12):'HP: '+fmt(g.hp)+' → '+fmt(Math.min(g.maxHp,g.hp+g.maxHp*.2));if(u.target==='economy')return 'Economia da run';const p=PLANTS.find(p=>affects(u,p));if(!p||!u.effects?.length)return '';const a=g.stats(p),b=g.stats(p,{extra:u}),key=u.effects[0].stat;return targetName(p.id)+': '+fmt(a[key]||0)+' → '+fmt(b[key]||0)}
function upgradeCards(choices){return choices.map(u=>{const plant=PLANTS.find(p=>affects(u,p));return '<button class="choice" data-upgrade="'+u.id+'"><span class="rarity '+u.rarity+'">'+RARITIES[u.rarity].label+'</span>'+(plant?'<img alt="" src="'+images[plant.id]+'">':'')+'<span class="target">'+targetName(u.target)+'</span><strong>'+u.name+'</strong><p>'+u.desc+'</p><span class="(d-none) before">'+preview(u)+'</span></button>'}).join('')}
function bindUpgradeChoices(kind){document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(!g.upgrade(b.dataset.upgrade))return;if(g.state==='intermission')close()});$('reroll').onclick=()=>g.rerollUpgrade()}
function onWave(choices,kind='upgrade'){
 if(kind==='gardenIntro'){const garden=choices[0],condition=garden.condition;show('<div class="garden-intro"><small>CHAPTER COMPLETE · NEW AREA DISCOVERED</small><h2 id="dialog-title">'+garden.name+'</h2><p>'+condition.summary+'</p><div class="condition-card"><span>GARDEN CONDITION</span><strong>'+condition.name+'</strong>'+condition.lines.map(line=>'<p>'+line+'</p>').join('')+'</div><p>Esta área tem base, plantas, invasores, Suns e rotas próprias. Os outros fronts continuarão em movimento quando você sair deles.</p><button class="primary" id="enter-garden">ENTRAR E PREPARAR</button></div>','gardenIntro');$('enter-garden').onclick=()=>{g.continueGardenIntro();close();toast(garden.name+' pronta · inicie o próximo capítulo quando quiser')};return}
 if(kind==='evolution'){show('<div class="evolution-title"><small>BOSS DERROTADO · MUTATION REWARD</small><h2 id="dialog-title">Escolha uma Evolution</h2><p>Esta decisão muda o comportamento da espécie e bloqueia os outros caminhos dela nesta run.</p></div><div class="choices evolution-choices">'+choices.map(e=>'<button class="choice evolution-choice" data-evolution="'+e.id+'"><img alt="" src="'+plantImage(e.plant,e.id)+'"><span class="target">'+targetName(e.plant)+'</span><strong>'+e.name+'</strong><p>'+e.description+'</p><span class="before"><b>COMO MUDA:</b> '+e.detail+'</span></button>').join('')+'</div>','evolution');document.querySelectorAll('[data-evolution]').forEach(b=>b.onclick=()=>{if(g.selectEvolution(b.dataset.evolution)&&g.state==='intermission')close()});return}
 if(kind==='bossReward'){show('<div class="evolution-title"><small>BOSS DEFEATED · FULLY EVOLVED</small><h2 id="dialog-title">Escolha uma Boss Reward</h2><p>Seu jardim atingiu todo o potencial evolutivo. Fortaleça a build inteira para o próximo capítulo.</p></div><div class="choices">'+upgradeCards(choices)+'</div><button id="reroll" class="reroll" '+(g.rerolls?'':'disabled')+'>REROLL ('+g.rerolls+')</button>','bossReward');bindUpgradeChoices(kind);return}
 if(kind==='expansion'){show('<small>CAPÍTULO '+(Math.floor(g.wave/10)+1)+'</small><h2 id="dialog-title">Expanda seu jardim</h2><p>Mais espaço para plantar também abre ou reforça uma rota de invasão.</p><div class="choices expansion-choices">'+choices.map(s=>'<button class="choice" data-sector="'+s.id+'"><span class="rarity rare">'+TERRAIN[s.terrain].name+'</span><strong>'+s.name+'</strong><p>+'+tileCount(s)+' tiles plantáveis</p><span class="before">'+TERRAIN[s.terrain].description+'<br><b>ATENÇÃO:</b> rota '+s.spawnEdge.toUpperCase()+'</span></button>').join('')+'</div>','expansion');document.querySelectorAll('[data-sector]').forEach(b=>b.onclick=()=>{if(g.expandSector(b.dataset.sector))close()});return}
 show('<small>WAVE '+g.wave+' CONCLUÍDA · +1 PLANT FOOD</small><h2 id="dialog-title">Escolha como crescer.</h2><p>As primeiras opções favorecem as espécies já usadas. Raros e épicos criam interações.</p><div class="choices">'+upgradeCards(choices)+'</div><button id="reroll" class="reroll" '+(g.rerolls?'':'disabled')+'>REROLL ('+g.rerolls+')</button>','upgrade');bindUpgradeChoices(kind);
}
function menu(){g.paused=true;show('<div class="main-menu"><div class="menu-art">'+['sunflower','peashooter','wallNut','repeater'].map(id=>'<img alt="" src="'+images[id]+'">').join('')+'</div><h2 id="dialog-title">Garden<span>LAST STAND</span></h2><p>Construa defesas. Especialize plantas. Administre múltiplos fronts.</p><button class="primary play" id="play">'+icon('play')+' '+(started&&g.state!=='over'?'Continuar run':'Jogar')+'</button><div class="menu-grid"><button id="almanac">'+icon('plants')+'Almanac</button><button id="meta">'+icon('upgrades')+'Melhorias</button><button id="stats">'+icon('stats')+'Estatísticas</button><button id="save-menu">'+icon('save')+'Save</button></div><button id="settings" style="margin-top:15px">'+icon('settings')+' Configurações</button><p><small>Recorde: wave '+meta.highestWave+' · Bosses: '+meta.bossStats.totalBossesDefeated+' · '+meta.seeds+' Seeds</small></p></div>','menu');$('play').onclick=()=>{if(!started||g.state==='over')newRun();else if(['upgrade','bossReward','evolution','expansion','gardenIntro'].includes(g.state))onWave(g.choices,g.state);else close()};$('almanac').onclick=()=>almanac();$('meta').onclick=metaMenu;$('stats').onclick=statistics;$('save-menu').onclick=saveMenu;$('settings').onclick=settings;update()}
function settings(){show(title('Configurações')+'<label class="setting"><span><b>Iniciar waves automaticamente</b><br><small>15s antes da primeira; 9s entre waves.</small></span><input type="checkbox" id="auto" '+(meta.settings.autoStart?'checked':'')+'></label><p>Atalhos: 1–7 plantas, X pá, espaço pausa, Esc cancela. Cooldowns usam tempo da simulação; Suns usam tempo real em 1×/2×/3×.</p>','settings');bindBack();$('auto').onchange=()=>{meta.settings.autoStart=$('auto').checked;g.autoStart=meta.settings.autoStart;persist();update()}}
function saveMenu(){show(title('Seu progresso')+'<p>O schema v3 preserva saves v1/v2 e adiciona Garden Tools e estatísticas de boss. A run ativa não é salva.</p><div class="save-actions"><button id="save">Salvar agora</button><button id="export">Exportar TXT</button><button id="import-btn">Importar TXT</button></div><button class="danger" id="reset">Resetar progresso</button>','save');bindBack();$('save').onclick=()=>persist()&&toast('Progresso salvo.');$('export').onclick=()=>download(meta);$('import-btn').onclick=()=>$('import').click();$('reset').onclick=()=>{show(title('Resetar progresso')+'<p>Todos os Seeds, masteries, Garden Tools e estatísticas serão apagados.</p><button id="confirm-reset" class="danger">Confirmar reset</button>','reset');bindBack(saveMenu);$('confirm-reset').onclick=()=>{meta=fresh();persist();started=false;g.meta=meta;g.reset();menu()}}}
$('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>100000)throw Error('Arquivo grande demais.');const incoming=validate(JSON.parse(await f.text()));show(title('Importar progresso')+'<p>Substituir o progresso atual por '+incoming.seeds+' Seeds e recorde '+incoming.highestWave+'?</p><button class="primary" id="confirm-import">Confirmar</button>','import');bindBack(saveMenu);$('confirm-import').onclick=()=>{meta=incoming;persist();g.meta=meta;g.reset();started=false;menu();toast('Save migrado para v3.')}}catch(err){toast('Importação recusada: '+err.message)}finally{e.target.value=''}};
function statistics(){show(title('Estatísticas')+'<div class="metric-grid">'+[['Recorde',meta.highestWave],['Runs',meta.totalRuns],['Bosses',meta.bossStats.totalBossesDefeated],['Maior boss wave',meta.bossStats.highestBossWave],['Planta favorita',targetName(meta.favorites.plant)||'—'],['Evolution favorita',EVOLUTIONS.find(e=>e.id===meta.favorites.evolution)?.name||'—'],['Seeds',meta.seeds],...METRICS.map(k=>[metricLabels[k],meta.statistics[k]])].map(([k,v])=>'<div>'+k+'<b>'+fmtOrText(v)+'</b></div>').join('')+'</div>','statistics');bindBack()}
const fmtOrText=v=>typeof v==='number'?fmt(v):v;
const toolDefs={gloves:{name:'Gardening Gloves',max:2,desc:['+22% no raio de coleta manual','Clique coleta Suns próximos junto']},basket:{name:'Sun Basket',max:3,desc:['+3s de duração dos Suns','+6s de duração dos Suns','+9s de duração dos Suns']},magnet:{name:'Sun Magnet',max:3,desc:['Seu cursor atrai Suns próximos · raio 1,4','Maior raio e atração mais forte · raio 2,25','Grande raio magnético e coleta muito rápida · raio 3,25']},reroll:{name:'Seed Satchel',max:3,desc:['Comece com +1 Reroll','Comece com +2 Rerolls','Comece com +3 Rerolls']}};
function metaMenu(){show(title('Melhorias permanentes')+'<p><b>'+meta.seeds+' Seeds</b> · vantagens modestas para a próxima run.</p><h3>Garden Tools</h3>'+Object.entries(toolDefs).map(([k,d])=>metaRow(meta.gardenTools,k,d.name,d.desc[Math.min(meta.gardenTools[k],d.max-1)],d.max)).join('')+'<h3>Mastery</h3>'+PLANTS.map(p=>metaRow(meta.plantMastery,p.id,p.name,masteryText(p),10)).join('')+'<h3>Jardim</h3>'+metaRow(meta,'economy','Starting Sun','+10 Sun inicial por nível',10)+metaRow(meta,'fortress','Base HP','+5% HP por nível',10),'meta');bindBack();document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const [group,key,max]=b.dataset.buy.split(':');buy(group==='meta'?meta:meta[group],key,Number(max))})}
function metaRow(obj,key,name,desc,max){const lv=obj[key],cost=12+lv*10;return '<div class="meta-row"><div><b>'+name+' · '+lv+'/'+max+'</b><small>'+desc+'</small></div><button data-buy="'+(obj===meta?'meta':obj===meta.gardenTools?'gardenTools':'plantMastery')+':'+key+':'+max+'" '+(lv>=max||meta.seeds<cost?'disabled':'')+'>'+(lv>=max?'Máximo':cost+' Seeds')+'</button></div>'}
function buy(obj,key,max){const cost=12+obj[key]*10;if(obj[key]<max&&meta.seeds>=cost){meta.seeds-=cost;obj[key]++;persist();metaMenu()}}
function masteryText(p){const base=p.id==='wallNut'?'+3% HP/nível':p.id==='sunflower'?'+2% Sun/nível':p.id==='potatoMine'?'+3% dano/nível':'+2% dano/nível',milestones={peashooter:'M5: primeira unidade −10% · M10: 5% ervilha extra',repeater:'M5: cooldown −10% · M10: 5% ervilha extra',sunflower:'M5: Suns +2s · M10: primeiro Sun/wave +10',bonkChoy:'M5: ataque +5% · M10: heavy punch antecipado',cabbagePult:'M5: área +10% · M10: primeiro impacto/wave +30% área',potatoMine:'M5: arma 15% antes · M10: primeira explosão/wave +25% dano',wallNut:'M5: cura 5%/wave · M10: primeira unidade +10% HP'};return base+' · '+milestones[p.id]}
function almanac(section='plants',filter='all'){const nav='<div class="tabs almanac-nav">'+[['plants','PLANTS'],['invaders','INVADERS'],['elites','ELITE MODIFIERS']].map(([id,label])=>'<button data-almanac="'+id+'" class="'+(section===id?'active':'')+'">'+label+'</button>').join('')+'</div>';let body='';if(section==='plants')body='<div class="tabs">'+Object.entries(CLASSES).map(([id,n])=>'<button data-class="'+id+'" class="'+(filter===id?'active':'')+'">'+n+'</button>').join('')+'</div><div class="collection">'+PLANTS.filter(p=>filter==='all'||p.class===filter).map(p=>'<button data-detail="'+p.id+'"><img alt="" src="'+images[p.id]+'"><b>'+p.name+'</b><small>'+CLASSES[p.class]+'</small><strong>'+p.baseCost+' Sun</strong><small>Mastery '+meta.plantMastery[p.id]+'/10</small><p>'+p.role+'</p></button>').join('')+'</div>';else if(section==='invaders')body='<div class="collection enemy-collection">'+ZOMBIES.map(z=>'<article><img alt="'+z.name+'" src="'+enemyImages[z.id]+'"><b>'+z.name+'</b><small class="enemy-role">'+z.roleLabel+'</small><strong>HP '+fmt(z.hp)+' · SPD '+fmt(z.speed)+' · THREAT '+fmt(z.threatCost)+'</strong><p><b>'+z.ability+'</b> '+z.description+'</p></article>').join('')+'</div>';else body='<div class="collection elite-collection">'+Object.values(ELITE_MODIFIERS).map(e=>'<article><span class="elite-emblem '+e.id+'">◆</span><b>'+e.name+'</b><small>'+e.label+' · THREAT ×'+fmt(e.threatMultiplier)+'</small><p>'+e.description+'</p></article>').join('')+'</div>';show(title('Garden Almanac')+nav+body,'almanac');bindBack();document.querySelectorAll('[data-almanac]').forEach(b=>b.onclick=()=>almanac(b.dataset.almanac));document.querySelectorAll('[data-class]').forEach(b=>b.onclick=()=>almanac('plants',b.dataset.class));document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>plantDetail(b.dataset.detail,filter))}
const statNames={hp:'HP máximo',damage:'Dano',attackInterval:'Intervalo de ataque (s)',dps:'DPS médio',range:'Alcance',projectileCount:'Projéteis',splashRadius:'Raio da área',productionInterval:'Produção (s)',sunAmount:'Sun por pickup',armTime:'Tempo para armar',damageReduction:'Redução',regen:'Cura entre waves'};
function plantDetail(id,filter){const p=PLANTS.find(p=>p.id===id),s=g.stats(p,{permanent:true}),base={...p,dps:p.attackInterval?p.damage*(p.projectileCount||1)/p.attackInterval:0},evos=EVOLUTIONS.filter(e=>e.plant===id);show(title(p.name)+'<div class="plant-detail-head"><img alt="'+p.name+'" src="'+images[id]+'"><div><b>'+CLASSES[p.class]+' · Mastery '+meta.plantMastery[id]+'/10</b><p>'+p.role+'</p><small>'+masteryText(p)+'</small></div></div><table class="stat-table"><tbody>'+Object.keys(statNames).filter(k=>s[k]!==undefined&&(s[k]>0||k==='hp')).map(k=>'<tr><td>'+statNames[k]+'</td><td>'+fmt(base[k]||0)+'</td><td>'+fmt(s[k])+'</td></tr>').join('')+'</tbody></table><h3>Possible Evolutions</h3><div class="food-levels">'+evos.map(e=>'<div class="evolution-entry"><img alt="'+e.name+'" src="'+plantImage(e.plant,e.id)+'"><span><b>'+e.name+'</b><br>'+e.description+'</span></div>').join('')+'</div><h3>Plant Food</h3><div class="food-levels"><div><b>LV 1</b> · Forma base</div>'+PLANT_LEVELS[id].map((l,i)=>'<div><b>LV '+(i+2)+'</b> · '+l.desc+'</div>').join('')+'</div><h3>Synergies</h3><p>'+({bonkChoy:'BODYGUARD · combine com Wall-Nut.',sunflower:'GARDEN AURA · sustenta vizinhas.',repeater:'CROSSFIRE · forme pares de Shooters.',peashooter:'CROSSFIRE · forme pares de Shooters.',cabbagePult:'HIGH GROUND · expanda ao leste.',wallNut:'FORTIFIED SOIL · expanda ao sul.',potatoMine:'FERTILE SOIL · primeira planta mais barata.'}[id])+'</p>','detail');bindBack(()=>almanac('plants',filter))}
